package io.github.dream07code.innovationspace.points;import io.github.dream07code.innovationspace.security.SessionPrincipal;import io.github.dream07code.innovationspace.common.api.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;@Service public class RankingService{private final JdbcTemplate jdbc;public RankingService(JdbcTemplate j){jdbc=j;}public Map<String,Object> overall(int page,int size){var rows=jdbc.queryForList("SELECT m.id member_id,m.name display_name,m.direction_id,COALESCE(SUM(p.delta),0) points FROM member m JOIN app_user u ON u.member_id=m.id LEFT JOIN point_ledger p ON p.member_id=m.id WHERE m.membership_status='ACTIVE' GROUP BY m.id,m.name,m.direction_id ORDER BY points DESC,m.id ASC LIMIT ? OFFSET ?",size,(page-1)*size);long total=jdbc.queryForObject("SELECT COUNT(*) FROM member WHERE membership_status='ACTIVE'",Long.class);return Map.of("items",rows,"page",page,"size",size,"total",total);}}
